#include <iostream>
#include <vector>

void extremes(const std::vector<int>& values, int& lowest, int& highest)
{
    lowest = values[0];
    highest = values[0];

    for (std::size_t i = 1; i < values.size(); ++i)
    {
        if (values[i] < lowest) lowest = values[i];
        if (values[i] > highest) highest = values[i];
    }
}

int main()
{
    std::vector<int> values{};
    int x{};

    while (std::cin >> x) values.push_back(x);

    if (values.empty())
    {
        std::cout << "empty\n";
        return 0;
    }

    int lowest{};
    int highest{};
    extremes(values, lowest, highest);

    std::cout << "min " << lowest << "\n";
    std::cout << "max " << highest << "\n";

    return 0;
}
